import { outbox } from './outbox';
import { resolve } from './conflicts';

export const BATCH_SIZE = 50;
export const MAX_BACKOFF_MS = 60000;
export const SYNC_INTERVAL_MS = 15 * 60 * 1000;

export async function runSync(api, db) {
  const rows = await outbox.peek(db, BATCH_SIZE);
  if (rows.length) await api.push(rows);
  const changes = await pullChanges(api, db);
  for (const change of changes) await resolve(db, change);
}

export async function pullChanges(api, db) {
  const cursor = await db.getSetting('sync_cursor');
  return api.pull({ since: cursor });
}

