export const OUTBOX_LIMIT = 500;

export const outbox = {
  async enqueue(db, op) {
    const id = newId();
    await db.run('INSERT INTO outbox (id, op, created_at) VALUES (?, ?, ?)', [id, JSON.stringify(op), Date.now()]);
    return id;
  },
  async peek(db, n) {
    return db.all('SELECT id, op FROM outbox ORDER BY created_at LIMIT ?', [n]);
  },
  async markSent(db, ids) {
    await db.run(`DELETE FROM outbox WHERE id IN (${ids.map(() => '?').join(',')})`, ids);
  },
};

