// Last writer wins, using the server's updatedAt (never the device clock).
export async function resolve(db, change) {
  const local = await db.get('SELECT updated_at FROM waypoints WHERE id = ?', [change.id]);
  if (!local || change.updatedAt > local.updated_at) {
    await db.run('REPLACE INTO waypoints (id, name, notes, updated_at) VALUES (?, ?, ?, ?)',
      [change.id, change.name, change.notes, change.updatedAt]);
  }
}

