import { DISTANCE_FILTER_M } from './backgroundLocation';

export const MIN_ACCURACY_M = 30;
export const FLUSH_BATCH = 20;
export const MAX_SPEED_MS = 12;

let buffer = [];

export async function onLocation(db, fix) {
  if (fix.accuracy > MIN_ACCURACY_M) return;
  buffer.push(fix);
  if (buffer.length >= FLUSH_BATCH) {
    const batch = buffer;
    buffer = [];
    await db.transaction((tx) => batch.forEach((p) => tx.run('INSERT INTO track_points VALUES (?,?,?,?)', [p.t, p.lat, p.lon, p.alt])));
  }
}

