import { Linking, AppState } from 'react-native';

export type PermState = 'granted' | 'denied' | 'blocked';

export async function requestLocation(perms, background = false): Promise<PermState> {
  const fg = await perms.request('location.whenInUse');
  if (fg !== 'granted') return fg === 'blocked' ? 'blocked' : 'denied';
  if (!background) return 'granted';
  return perms.request('location.always');
}

