export function onPurchaseUpdate(api) {
  return RNIap.purchaseUpdatedListener(async (purchase) => {
    const res = await api.verifyReceipt(purchase);
    if (res.entitled) await RNIap.finishTransaction({ purchase, isConsumable: false });
  });
}

export async function restore(api) {
  const purchases = await RNIap.getAvailablePurchases();
  return api.syncEntitlements(purchases);
}

