export const MAX_CACHE_MB = 500;
export const TILE_TTL_DAYS = 30;

export async function putTile(fs, key, bytes) {
  const tmp = `${key}.tmp`;
  await fs.writeFile(tmp, bytes);
  await fs.rename(tmp, key);
}

export async function evictLru(fs, index) {
  while (index.totalBytes() > MAX_CACHE_MB * 1024 * 1024) {
    await fs.unlink(index.oldest());
  }
}

