export const MAX_REGION_TILES = 20000;
export const MIN_ZOOM = 10;
export const MAX_ZOOM = 16;
const PARALLEL_REQUESTS = 4;

export function planRegion(bbox) {
  const tiles = tilesFor(bbox, MIN_ZOOM, MAX_ZOOM);
  if (tiles.length > MAX_REGION_TILES) throw new Error('region too large');
  return tiles;
}

export async function download(queue, tiles) {
  return queue.run(tiles, { concurrency: PARALLEL_REQUESTS });
}

