export const SCHEMA_VERSION = 7;

const MIGRATIONS = {
  1: 'CREATE TABLE waypoints (id TEXT PRIMARY KEY, name TEXT, notes TEXT, updated_at INTEGER)',
  2: 'CREATE TABLE outbox (id TEXT PRIMARY KEY, op TEXT, created_at INTEGER)',
  // 3..7 add tracks, track_points, settings, tile_index, entitlements
};

export async function runMigrations(db) {
  let v = await db.pragma('user_version');
  while (v < SCHEMA_VERSION) {
    v += 1;
    await db.transaction((tx) => { tx.exec(MIGRATIONS[v]); tx.pragma(`user_version = ${v}`); });
  }
}

